    { const char * tb_v1198 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1198; }
    { const char * tb_v1199 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1199; }
    { const char * tb_v1200 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1200; }
