    { const char * tb_v1229 = "    // \\n остаётся \\n (как на Linux и Mac): одинаковый вывод в файл и в трубу\n"; *(const char * *)tb_grow(v_lines) = tb_v1229; }
    { const char * tb_v1230 = "    _setmode(_fileno(stdout), _O_BINARY);\n"; *(const char * *)tb_grow(v_lines) = tb_v1230; }
    { const char * tb_v1231 = "    _setmode(_fileno(stderr), _O_BINARY);\n"; *(const char * *)tb_grow(v_lines) = tb_v1231; }
    { const char * tb_v1232 = "    DWORD mode;\n"; *(const char * *)tb_grow(v_lines) = tb_v1232; }
    { const char * tb_v1233 = "    HANDLE out = GetStdHandle(STD_OUTPUT_HANDLE), err = GetStdHandle(STD_ERROR_HANDLE);\n"; *(const char * *)tb_grow(v_lines) = tb_v1233; }
    { const char * tb_v1234 = "    if (GetConsoleMode(out, &mode)) SetConsoleMode(out, mode | 0x0004);   // ENABLE_VIRTUAL_TERMINAL_PROCESSING\n"; *(const char * *)tb_grow(v_lines) = tb_v1234; }
    { const char * tb_v1235 = "    if (GetConsoleMode(err, &mode) && SetConsoleMode(err, mode | 0x0004)) tb_win_vt = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1235; }
    { const char * tb_v1236 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1236; }
    { const char * tb_v1237 = "    wchar_t **wa = CommandLineToArgvW(GetCommandLineW(), &n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1237; }
    { const char * tb_v1238 = "    if (wa && n > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1238; }
    { const char * tb_v1239 = "        char **a = malloc(sizeof(char *) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v1239; }
    { const char * tb_v1240 = "        if (a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1240; }
    { const char * tb_v1241 = "            for (int i = 0; i < n; i++) a[i] = tb_narrow(wa[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v1241; }
    { const char * tb_v1242 = "            a[n] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1242; }
    { const char * tb_v1243 = "            *argc = n; *argv = a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1243; }
    { const char * tb_v1244 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1244; }
    { const char * tb_v1245 = "        LocalFree(wa);\n"; *(const char * *)tb_grow(v_lines) = tb_v1245; }
    { const char * tb_v1246 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1246; }
    { const char * tb_v1247 = "    AddVectoredExceptionHandler(1, tb_win_overflow);\n"; *(const char * *)tb_grow(v_lines) = tb_v1247; }
    { const char * tb_v1248 = "    SetUnhandledExceptionFilter(tb_win_crashed);\n"; *(const char * *)tb_grow(v_lines) = tb_v1248; }
    { const char * tb_v1249 = "    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);\n"; *(const char * *)tb_grow(v_lines) = tb_v1249; }
    { const char * tb_v1250 = "    ULONG g = 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v1250; }
    { const char * tb_v1251 = "    SetThreadStackGuarantee(&g);\n"; *(const char * *)tb_grow(v_lines) = tb_v1251; }
    { const char * tb_v1252 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1252; }
    { const char * tb_v1253 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1253; }
    { const char * tb_v1254 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1254; }
    { const char * tb_v1255 = "// main() зовёт tb_guard_init(): на Windows ей нужны ещё argc и argv из main\n"; *(const char * *)tb_grow(v_lines) = tb_v1255; }
    { const char * tb_v1256 = "#define tb_guard_init() tb_win_init(&argc, &argv)\n"; *(const char * *)tb_grow(v_lines) = tb_v1256; }
    { const char * tb_v1257 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1257; }
    { const char * tb_v1258 = "TB_API void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1258; }
    { const char * tb_v1259 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v1259; }
    { const char * tb_v1260 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v1260; }
    { const char * tb_v1261 = "    ss.ss_sp = alt; ss.ss_size = sizeof alt; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1261; }
    { const char * tb_v1262 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1262; }
    { const char * tb_v1263 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v1263; }
    { const char * tb_v1264 = "    memset(&sa, 0, sizeof sa);\n"; *(const char * *)tb_grow(v_lines) = tb_v1264; }
    { const char * tb_v1265 = "    sa.sa_sigaction = tb_on_segv;\n"; *(const char * *)tb_grow(v_lines) = tb_v1265; }
    { const char * tb_v1266 = "    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v1266; }
    { const char * tb_v1267 = "    sigaction(SIGSEGV, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1267; }
    { const char * tb_v1268 = "    sigaction(SIGBUS, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1268; }
    { const char * tb_v1269 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1269; }
    { const char * tb_v1270 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1270; }
    { const char * tb_v1271 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
    { const char * tb_v1273 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1273; }
    { const char * tb_v1274 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1274; }
    { const char * tb_v1275 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v1275; }
    { const char * tb_v1276 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v1276; }
    { const char * tb_v1277 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v1277; }
    { const char * tb_v1278 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v1278; }
    { const char * tb_v1279 = "TB_API _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1279; }
    { const char * tb_v1280 = "TB_API _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1280; }
    { const char * tb_v1281 = "TB_API int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1281; }
    { const char * tb_v1282 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1282; }
    { const char * tb_v1283 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1283; }
    { const char * tb_v1284 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1284; }
    { const char * tb_v1285 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1285; }
    { const char * tb_v1286 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1286; }
    { const char * tb_v1287 = "TB_API void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1287; }
    { const char * tb_v1288 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1288; }
    { const char * tb_v1289 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1289; }
    { const char * tb_v1290 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1290; }
    { const char * tb_v1291 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v1291; }
    { const char * tb_v1292 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1292; }
    { const char * tb_v1293 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1293; }
    { const char * tb_v1294 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v1294; }
    { const char * tb_v1295 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v1295; }
    { const char * tb_v1296 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1296; }
    { const char * tb_v1297 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1297; }
    { const char * tb_v1298 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1298; }
    { const char * tb_v1299 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1299; }
    { const char * tb_v1300 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1300; }
    { const char * tb_v1301 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v1301; }
    { const char * tb_v1302 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1302; }
    { const char * tb_v1303 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1303; }
    { const char * tb_v1304 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1304; }
    { const char * tb_v1305 = "    c->used += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1305; }
    { const char * tb_v1306 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1306; }
    { const char * tb_v1307 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1307; }
    { const char * tb_v1308 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v1308; }
    { const char * tb_v1309 = "TB_API _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1309; }
    { const char * tb_v1310 = "TB_API _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1310; }
    { const char * tb_v1311 = "TB_INL tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1311; }
    { const char * tb_v1312 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1312; }
    { const char * tb_v1313 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1313; }
    { const char * tb_v1314 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1314; }
    { const char * tb_v1315 = "        tb_marks = realloc(tb_marks, sizeof(tb_mark) * tb_capmarks);\n"; *(const char * *)tb_grow(v_lines) = tb_v1315; }
    { const char * tb_v1316 = "        if (tb_marks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1316; }
    { const char * tb_v1317 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1317; }
    { const char * tb_v1318 = "    tb_marks[tb_temp_depth] = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1318; }
    { const char * tb_v1319 = "    tb_temp_depth += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1319; }
    { const char * tb_v1320 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1320; }
    { const char * tb_v1321 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1321; }
    { const char * tb_v1322 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v1322; }
    { const char * tb_v1323 = "TB_API int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1323; }
    { const char * tb_v1324 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1324; }
    { const char * tb_v1325 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1325; }
    { const char * tb_v1326 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1326; }
    { const char * tb_v1327 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v1327; }
    { const char * tb_v1328 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v1328; }
    { const char * tb_v1329 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v1329; }
    { const char * tb_v1330 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1330; }
    { const char * tb_v1331 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1331; }
    { const char * tb_v1332 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1332; }
    { const char * tb_v1333 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v1333; }
    { const char * tb_v1334 = "TB_API _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1334; }
    { const char * tb_v1335 = "TB_API _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1335; }
    { const char * tb_v1336 = "TB_API _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1336; }
    { const char * tb_v1337 = "TB_INL void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1337; }
    { const char * tb_v1338 = "TB_INL void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1338; }
    { const char * tb_v1339 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1339; }
    { const char * tb_v1340 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1340; }
    { const char * tb_v1341 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1341; }
    { const char * tb_v1342 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v1342; }
    { const char * tb_v1343 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1343; }
    { const char * tb_v1344 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1344; }
    { const char * tb_v1345 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1345; }
    { const char * tb_v1346 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1346; }
    { const char * tb_v1347 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v1347; }
    { const char * tb_v1348 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1348; }
    { const char * tb_v1349 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1349; }
    { const char * tb_v1350 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1350; }
    { const char * tb_v1351 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1351; }
    { const char * tb_v1352 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1352; }
    { const char * tb_v1353 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1353; }
    { const char * tb_v1354 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1354; }
    { const char * tb_v1355 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1355; }
    { const char * tb_v1356 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1356; }
    { const char * tb_v1357 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1357; }
    { const char * tb_v1358 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1358; }
    { const char * tb_v1359 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1359; }
    { const char * tb_v1360 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1360; }
    { const char * tb_v1361 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1361; }
    { const char * tb_v1362 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1362; }
    { const char * tb_v1363 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1363; }
    { const char * tb_v1364 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1364; }
    { const char * tb_v1365 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1365; }
    { const char * tb_v1366 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1366; }
    { const char * tb_v1367 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1367; }
    { const char * tb_v1368 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1368; }
    { const char * tb_v1369 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1369; }
    { const char * tb_v1370 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1370; }
    { const char * tb_v1371 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1371; }
    { const char * tb_v1372 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1372; }
    { const char * tb_v1373 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v1373; }
    { const char * tb_v1374 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1374; }
    { const char * tb_v1375 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1375; }
    { const char * tb_v1376 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v1376; }
    { const char * tb_v1377 = "#define TB_GPG (1LL << TB_GSH)\n"; *(const char * *)tb_grow(v_lines) = tb_v1377; }
