    { const char * tb_v1492 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v1492; }
    { const char * tb_v1493 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1493; }
    { const char * tb_v1494 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v1494; }
    { const char * tb_v1495 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v1495; }
    { const char * tb_v1496 = "TB_INL char *tb_gblock(uintptr_t a, tb_gpage **out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1496; }
