    { const char * tb_v2340 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v2340; }
    { const char * tb_v2341 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2341; }
    { const char * tb_v2342 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v2342; }
    { const char * tb_v2343 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v2343; }
