    { const char * tb_v2623 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2623; }
    { const char * tb_v2624 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2624; }
    { const char * tb_v2625 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2625; }
