    { const char * tb_v2671 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2671; }
    { const char * tb_v2672 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v2672; }
    { const char * tb_v2673 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2673; }
    { const char * tb_v2674 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v2674; }
