    { const char * tb_v2699 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2699; }
    { const char * tb_v2700 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2700; }
    { const char * tb_v2701 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v2701; }
    { const char * tb_v2702 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2702; }
    { const char * tb_v2703 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2703; }
    { const char * tb_v2704 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2704; }
    { const char * tb_v2705 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2705; }
    { const char * tb_v2706 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2706; }
    { const char * tb_v2707 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2707; }
