    { const char * tb_v2736 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2736; }
    { const char * tb_v2737 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v2737; }
    { const char * tb_v2738 = "TB_INL void tb_dpre2(tb_dict *d, unsigned long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2738; }
